#pragma warning disable CS1591

namespace Codec.Aac;

/// <summary>
/// Perceptual Noise Substitution (PNS) — ISO/IEC 14496-3 §4.6.13. PNS replaces a
/// scale-factor band's spectrum with white noise scaled by a transmitted energy
/// value (carried in the band's "scale factor"). The noise is generated by a
/// deterministic LFSR so decoding is reproducible; correlation between L/R noise
/// is left independent (the m/s mask never couples PNS bands in this decoder).
/// <para>
/// LTP (Long-Term Prediction, AAC-Main / AAC-LTP profiles) is intentionally
/// unimplemented — AAC-LC does not use it.
/// </para>
/// </summary>
internal static class AacPns {

  /// <summary>The Huffman-codebook index that signals noise substitution.</summary>
  public const int NoiseHcb = 13;

  /// <summary>
  /// Replaces every PNS band (codebook 13) of one channel with scaled pseudo-noise.
  /// The per-band energy comes from the noise scale factor: amplitude
  /// <c>2^(sf/4)</c> normalised by the band's RMS (ISO/IEC 14496-3 §4.6.13.3).
  /// <paramref name="seed"/> threads LFSR state across bands so the whole channel
  /// is one deterministic noise sequence.
  /// </summary>
  public static void Apply(float[] spectrum, IcsInfo ics, int[][] codebooks, int[][] scaleFactors, ref uint seed) {
    var groupWindowStart = 0;
    var groupBins = ics.IsEightShort ? AacFilterBank.ShortFrameSize : AacFilterBank.LongFrameSize;
    for (var g = 0; g < ics.WindowGroupCount; ++g) {
      var windowsInGroup = ics.WindowGroupLength[g];
      for (var sfb = 0; sfb < ics.MaxSfb; ++sfb) {
        if (codebooks[g][sfb] != NoiseHcb) continue;
        var sfbStart = ics.SwbOffset[sfb];
        var sfbEnd = ics.SwbOffset[sfb + 1];
        var amplitude = MathF.Pow(2f, scaleFactors[g][sfb] / 4f);
        for (var w = 0; w < windowsInGroup; ++w) {
          var baseBin = (groupWindowStart + w) * groupBins;
          GenerateNoiseBand(spectrum, baseBin + sfbStart, baseBin + sfbEnd, ref seed, amplitude);
        }
      }
      groupWindowStart += windowsInGroup;
    }
  }

  /// <summary>
  /// Fills <c>[start, end)</c> with zero-mean noise whose RMS equals
  /// <paramref name="amplitude"/>. The seed is advanced by a 32-bit LCG so a given
  /// seed always yields the same band — deterministic and decorrelated.
  /// </summary>
  public static void GenerateNoiseBand(float[] spectrum, int start, int end, ref uint seed, float amplitude) {
    var count = end - start;
    if (count <= 0) return;
    var temp = new float[count];
    double energy = 0;
    for (var k = 0; k < count; ++k) {
      seed = seed * 1664525u + 1013904223u; // numerical-recipes LCG
      var raw = (int)(seed >> 1) - (int)(1u << 30);
      temp[k] = raw;
      energy += (double)raw * raw;
    }
    var rms = Math.Sqrt(energy / count);
    var norm = rms > 0 ? amplitude / (float)rms : 0f;
    for (var k = 0; k < count; ++k)
      spectrum[start + k] = temp[k] * norm;
  }
}
